/* DARLEK CAAN RAG SYNTHESIS - Autonomous Generation G-105 [2026-09-20T03:41:58.111Z] */
@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@400;500;600;700;800;900&family=Share+Tech+Mono&family=JetBrains+Mono:wght@400;500;600&family=Inter:wght@400;500;600&family=Outfit:wght@500;600;700&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: #000000;
    --foreground: #e0e0e0;
    --card: #080303;
    --card-foreground: #e0e0e0;
    --popover: #0a0505;
    --popover-foreground: #e0e0e0;
    --primary: #ff3333;
    --primary-foreground: #ffffff;
    --secondary: #1a0808;
    --secondary-foreground: #f0f0f0;
    --muted: #1f0d0d;
    --muted-foreground: #888888;
    --accent: #2a1010;
    --accent-foreground: #ffffff;
    --destructive: #dc2626;
    --destructive-foreground: #ffffff;
    --border: #331111;
    --input: #331111;
    --ring: #ff3333;
    --radius: 0.375rem;

    --font-orbitron: 'Orbitron', 'Share Tech Mono', ui-monospace, monospace;
    --font-share-tech-mono: 'Share Tech Mono', ui-monospace, monospace;
    --font-sans: 'Inter', ui-sans-serif, system-ui, sans-serif;
    --font-display: 'Outfit', ui-sans-serif, system-ui, sans-serif;
    --font-mono: 'JetBrains Mono', 'Share Tech Mono', ui-monospace, SFMono-Regular, monospace;

    --color-bg-primary: #000000;
    --color-text-primary: #e0e0e0;
    --color-accent-red: #ff3333;
    --color-border-dark: #331111;
  }

  *, ::before, ::after {
    box-sizing: border-box;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  html, 
  body {
    direction: ltr !important;
    text-align: left;
    unicode-bidi: normal;
    background-color: var(--color-bg-primary);
    color: var(--color-text-primary);
    font-family: var(--font-sans);
    min-height: 100vh;
    overflow-x: hidden;
  }

  input, 
  textarea, 
  select {
    direction: ltr !important;
    text-align: left !important;
    unicode-bidi: normal !important;
  }
}

@layer components {
  /* ==========================================================================
     Dalek Form Controls
     ========================================================================== */
  .dalek-input {
    direction: ltr !important;
    text-align: left !important;
    unicode-bidi: normal !important;
    background: rgba(10, 10, 10, 0.9);
    color: #f0f0f0;
    border: 1px solid var(--color-border-dark);
    border-radius: var(--radius);
    font-family: var(--font-share-tech-mono), monospace;
    outline: none;
    will-change: border-color, box-shadow;
    transition: border-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.15s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .dalek-input:focus {
    border-color: var(--color-accent-red);
    box-shadow: 0 0 8px rgba(255, 32, 32, 0.2);
  }

  .dalek-btn {
    background: rgba(20, 20, 20, 0.85);
    border: 1px solid var(--color-border-dark);
    color: #d0d0d0;
    border-radius: var(--radius);
    font-family: var(--font-orbitron), sans-serif;
    cursor: pointer;
    will-change: background-color, border-color, color, box-shadow;
    transition: background-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), 
                border-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), 
                color 0.15s cubic-bezier(0.4, 0, 0.2, 1), 
                box-shadow 0.15s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .dalek-btn:hover {
    background: rgba(35, 15, 15, 0.95);
    border-color: var(--color-accent-red);
    color: #ffffff;
  }

  .dalek-btn-primary {
    background: rgba(180, 20, 20, 0.85);
    border-color: var(--color-accent-red);
    color: #ffffff;
  }

  .dalek-btn-primary:hover {
    background: rgba(220, 30, 30, 0.95);
    box-shadow: 0 0 10px rgba(255, 32, 32, 0.4);
  }

  /* ==========================================================================
     Custom Cyber/Dalek Scrollbars
     ========================================================================== */
  .dalek-scrollbar {
    scrollbar-width: thin;
    scrollbar-color: #331111 #080000;
  }

  .dalek-scrollbar::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }

  .dalek-scrollbar::-webkit-scrollbar-track {
    background: #080000;
  }

  .dalek-scrollbar::-webkit-scrollbar-thumb {
    background: #331111;
    border-radius: 3px;
  }

  .dalek-scrollbar::-webkit-scrollbar-thumb:hover {
    background: #ff2020;
  }

  .no-scrollbar {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }

  .no-scrollbar::-webkit-scrollbar {
    display: none;
  }

  /* ==========================================================================
     Effects & Animations
     ========================================================================== */
  .title-glow {
    text-shadow: 0 0 12px rgba(255, 32, 32, 0.6), 0 0 24px rgba(255, 32, 32, 0.3);
  }

  @keyframes pulse-red-anim {
    0%, 100% { opacity: 1; box-shadow: 0 0 4px #ff2020; }
    50% { opacity: 0.4; box-shadow: 0 0 10px #ff2020; }
  }

  @keyframes pulse-white-anim {
    0%, 100% { opacity: 1; box-shadow: 0 0 4px #ffffff; }
    50% { opacity: 0.4; box-shadow: 0 0 10px #ffffff; }
  }

  .pulse-red {
    animation: pulse-red-anim 2s infinite ease-in-out;
    will-change: opacity, box-shadow;
  }

  .pulse-white,
  .pulse-cyan {
    animation: pulse-white-anim 2s infinite ease-in-out;
    will-change: opacity, box-shadow;
  }

  .pulse-gold {
    animation: pulse-red-anim 2s infinite ease-in-out;
    will-change: opacity, box-shadow;
  }

  /* ==========================================================================
     Dalek Panels & Layout Containers
     ========================================================================== */
  .dalek-panel {
    background: rgba(10, 4, 4, 0.94);
    border: 1px solid rgba(255, 32, 32, 0.22);
    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.85), inset 0 0 16px rgba(255, 32, 32, 0.03);
    backdrop-filter: blur(12px);
  }

  .dalek-panel-header {
    border-bottom: 1px solid rgba(255, 32, 32, 0.15);
    font-family: var(--font-orbitron), sans-serif;
    letter-spacing: 0.12em;
  }

  /* ==========================================================================
     Screen Overlays & Textures
     ========================================================================== */
  .scanline-overlay::before {
    content: " ";
    display: block;
    position: absolute;
    inset: 0;
    background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.3) 50%);
    background-size: 100% 4px;
    z-index: 30;
    pointer-events: none;
    opacity: 0.35;
  }

  .grid-overlay {
    background-image: linear-gradient(rgba(255, 32, 32, 0.03) 1px, transparent 1px),
                      linear-gradient(90deg, rgba(255, 32, 32, 0.03) 1px, transparent 1px);
    background-size: 32px 32px;
  }

  .vignette {
    box-shadow: inset 0 0 120px rgba(0, 0, 0, 0.95);
  }

  .radial-bg {
    background: radial-gradient(circle at 50% 30%, rgba(35, 6, 6, 0.55) 0%, rgba(3, 1, 1, 0.98) 75%);
  }

  /* ==========================================================================
     Dalek Spinners & Animated Indicators
     ========================================================================== */
  .dalek-spinner {
    position: relative;
    width: 60px;
    height: 60px;
  }

  .dalek-spinner-outer {
    position: absolute;
    inset: 0;
    border: 2px solid transparent;
    border-top-color: #ff3333;
    border-radius: 50%;
    animation: spin-clockwise 1.5s linear infinite;
  }

  .dalek-spinner-middle {
    position: absolute;
    inset: 8px;
    border: 2px solid transparent;
    border-bottom-color: #ffffff;
    border-radius: 50%;
    animation: spin-counter 1.2s linear infinite;
  }

  .dalek-spinner-inner {
    position: absolute;
    inset: 16px;
    border: 2px solid transparent;
    border-left-color: #ff2020;
    border-radius: 50%;
    animation: spin-clockwise 0.8s linear infinite;
  }

  @keyframes spin-clockwise {
    to { transform: rotate(360deg); }
  }

  @keyframes spin-counter {
    to { transform: rotate(-360deg); }
  }

  @keyframes reboot-progress {
    0% { width: 0%; }
    100% { width: 100%; }
  }

  .slide-up {
    animation: slideUp 0.25s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  }

  @keyframes slideUp {
    from { transform: translateY(20px); opacity: 0; }
    to { transform: translateY(0); opacity: 1; }
  }

  .message-animate {
    animation: messageIn 0.2s ease-out forwards;
  }

  @keyframes messageIn {
    from { opacity: 0; transform: translateY(6px); }
    to { opacity: 1; transform: translateY(0); }
  }
}

/* Global Custom Scrollbars */
::-webkit-scrollbar { 
  width: 5px; 
  height: 5px;
}

::-webkit-scrollbar-track { 
  background: #080000; 
}

::-webkit-scrollbar-thumb { 
  background: #331111; 
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover { 
  background: #ff2020; 
}

* {
  scrollbar-width: thin;
  scrollbar-color: #331111 #080000;
}
